import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BlueBirdFlyProps = Record<string, any>;

const Cloud: React.FC<{ x: number; y: number; scale: number; color: string; speed: number }> = ({
  x,
  y,
  scale,
  color,
  speed,
}) => {
  const frame = useCurrentFrame();
  const offset = frame * speed;

  return (
    <div
      style={{
        position: "absolute",
        left: x - offset,
        top: y,
        transform: `scale(${scale})`,
        transition: "none",
      }}
    >
      <svg width="200" height="120" viewBox="0 0 200 120" fill={color}>
        <path d="M50,60 C20,60 0,45 0,25 C0,5 20,0 40,10 C50,-10 80,-10 90,10 C100,-5 130,-5 140,15 C150,5 180,5 190,25 C200,45 180,60 150,60 Z" />
      </svg>
    </div>
  );
};

const Bird: React.FC<{
  color: string;
  wingColor: string;
  beakColor: string;
  size: number;
  flapFreq: number;
}> = ({ color, wingColor, beakColor, size, flapFreq }) => {
  const frame = useCurrentFrame();
  
  // Flap animation: Rotates the wing
  const wingRotation = Math.sin(frame * flapFreq) * 25; 
  
  // Bobbing animation: Slight up and down movement of the whole bird body for realism
  const bobOffset = Math.sin(frame * 0.1) * 5;

  return (
    <div
      style={{
        width: size,
        height: size * 0.75,
        position: "relative",
        transform: `translateY(${bobOffset}px)`,
        transition: "none",
      }}
    >
      <svg viewBox="0 0 100 80" width="100%" height="100%" style={{ overflow: 'visible' }}>
        {/* Beak */}
        <path d="M85,25 L100,35 L85,45 Z" fill={beakColor} />
        
        {/* Tail */}
        <path d="M10,40 L-5,25 L-5,55 Z" fill={color} />

        {/* Body */}
        <path 
          d="M15,40 Q15,15 50,15 Q85,15 85,40 Q85,65 50,65 Q15,65 15,40 Z" 
          fill={color} 
        />
        
        {/* Eye */}
        <circle cx="75" cy="30" r="3" fill="white" />
        <circle cx="76" cy="29" r="1" fill="black" />

        {/* Wing Group: Pivots around the shoulder */}
        <g transform={`rotate(${wingRotation}, 50, 35)`}>
           <path 
            d="M35,35 Q50,10 70,35 Q50,55 35,35 Z" 
            fill={wingColor} 
            opacity="0.9"
            stroke="rgba(0,0,0,0.1)"
            strokeWidth="1"
           />
        </g>
      </svg>
    </div>
  );
};

const BlueBirdFly: React.FC<BlueBirdFlyProps> = ({
  backgroundColor = "#87CEEB",
  transparentBackground = false,
  durationInSeconds = 8,
  birdColor = "#1E90FF",
  wingColor = "#87CEFA",
  beakColor = "#FFA500",
  sunColor = "#FFD700",
  cloudColor = "#FFFFFF",
  birdSize = 150,
  flightSpeed = 1,
  flapFrequency = 0.5,
}) => {
  useFontLoader(["Fredoka One"]);
  
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Safety check for parser
  const actualBgColor = transparentBackground ? "transparent" : backgroundColor;
  const totalFrames = durationInSeconds * fps;

  // Flight path interpolation
  // Start completely off-screen left, end completely off-screen right
  const startX = -birdSize - 100;
  const endX = width + birdSize;
  
  // Calculate current X based on speed multiplier relative to duration
  // We want it to cross the screen. If flightSpeed is higher, it crosses faster/more times, 
  // but for a simple "fly across", we usually map 0->1 to start->end.
  // We'll stick to one full crossing over the duration.
  const currentX = interpolate(
    frame,
    [0, totalFrames],
    [startX, endX],
    { easing: Easing.linear }
  );

  // Vertical sine wave path
  const currentY = (height / 2) - (birdSize / 2) + Math.sin(frame * 0.05) * 40;

  return (
    <AbsoluteFill style={{ backgroundColor: actualBgColor, overflow: "hidden" }}>
      
      {/* Sun */}
      <div
        style={{
          position: "absolute",
          top: height * 0.1,
          right: width * 0.1,
          width: width * 0.15,
          height: width * 0.15,
          borderRadius: "50%",
          backgroundColor: sunColor,
          boxShadow: `0 0 40px ${sunColor}`,
          transform: `scale(${1 + Math.sin(frame * 0.02) * 0.05})`,
          transition: "none",
        }}
      />

      {/* Clouds (Background Layer) */}
      <Cloud x={width * 0.2} y={height * 0.2} scale={0.8} color={`${cloudColor}CC`} speed={0.2} />
      <Cloud x={width * 0.7} y={height * 0.5} scale={1.2} color={`${cloudColor}EE`} speed={0.3} />
      <Cloud x={width * 0.5} y={height * 0.8} scale={0.6} color={`${cloudColor}AA`} speed={0.15} />

      {/* Flying Bird */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          transform: `translateX(${currentX}px) translateY(${currentY}px)`,
          transition: "none",
        }}
      >
        <Bird 
          color={birdColor} 
          wingColor={wingColor} 
          beakColor={beakColor} 
          size={birdSize} 
          flapFreq={flapFrequency}
        />
      </div>
      
      {/* Optional Text or "Tweet" bubble could go here, but keeping it clean as requested */}
    </AbsoluteFill>
  );
};

export default BlueBirdFly;